using System;
using System.ComponentModel;

namespace go.arrays;

/// <summary>
/// The equality and hash every member of the inline-array family shares. A member is generated by go2cs-arrays-gen
/// and passes a reference to its first element and its length.
/// </summary>
/// <remarks>
/// Elements compare by Go's <c>==</c>, <see cref="builtin.AreEqual{T}(T, T)"/>: a NaN element makes two arrays unequal,
/// and <c>0</c> equals <c>-0</c>. The family holds only unmanaged elements, which are never pointers, so no nil
/// normalization arises.
/// </remarks>
[EditorBrowsable(EditorBrowsableState.Never)]
public static class InlineArrays
{
    /// <summary>
    /// Reports whether the <paramref name="length"/> elements from <paramref name="left"/> and from
    /// <paramref name="right"/> are equal, element by element.
    /// </summary>
    public static bool Equal<T>(ref T left, ref T right, int length) where T : unmanaged
    {
        for (int i = 0; i < length; i++)
        {
            if (!builtin.AreEqual(System.Runtime.CompilerServices.Unsafe.Add(ref left, i), System.Runtime.CompilerServices.Unsafe.Add(ref right, i)))
                return false;
        }

        return true;
    }

    /// <summary>
    /// The hash of the <paramref name="length"/> elements from <paramref name="first"/>, consistent with
    /// <see cref="Equal{T}"/>.
    /// </summary>
    public static int Hash<T>(ref T first, int length) where T : unmanaged
    {
        HashCode hash = new();

        for (int i = 0; i < length; i++)
            hash.Add(System.Runtime.CompilerServices.Unsafe.Add(ref first, i));

        return hash.ToHashCode();
    }
}
